/* Native controls retain the observed legacy layout with keyboard-accessible button behavior. */
.allianz-legacy{min-height:100vh;font-family:"Allianz Neo",sans-serif;}
.allianz-legacy .allianz-legacy-footer{margin-left:0;margin-right:0;padding-top:25px;margin-top:30px;background-color:#666;}
.allianz-legacy.new-york .allianz-legacy-footer{background-color:#f5f5f5;color:#5b5b5b;}
.allianz-legacy .hero-img picture{display:block;}
.allianz-legacy .hero-img picture>img{display:block;width:100%;height:auto;}
.allianz-legacy .allianz-legacy-editorial:empty{display:none;}
.allianz-legacy .allianz-legacy-accordion-trigger{cursor:pointer;margin:0;padding:9px 40px 11px 7px;position:relative;display:block;width:100%;color:#003781;background:transparent;border:0;text-align:left;font:inherit;}
.allianz-legacy .allianz-legacy-accordion-trigger:hover{background:#f7f7f7;}
.allianz-legacy .allianz-legacy-accordion-trigger:focus-visible{outline:2px solid #006192;outline-offset:2px;}
.allianz-legacy .allianz-legacy-accordion-icon{position:absolute;right:3px;top:9px;line-height:1;font-size:24px;}
.allianz-legacy .allianz-legacy-section-toggle,.allianz-legacy .allianz-legacy-footer-toggle{border:0;background:transparent;color:inherit;font:inherit;}
.allianz-legacy .allianz-legacy-section-toggle{position:absolute;right:0;top:0;padding:10px 15px;}
.allianz-legacy .allianz-legacy-print{padding:0;border:0;background:transparent;color:#0077c8;font:inherit;cursor:pointer;}
.allianz-legacy .allianz-legacy-print:hover{text-decoration:underline;}
.allianz-legacy .allianz-legacy-table-striped table tbody tr:nth-child(odd){background-color:#f9f9f9;}
.allianz-legacy .allianz-legacy-card-image{display:block;max-width:100%;height:auto;}
.allianz-legacy .allianz-legacy-subnav{padding-left:20px;list-style:none;}
@media(min-width:768px){.allianz-legacy .left-nav>.dropdown>.dropdown-menu{display:block;position:relative;float:none;background:transparent;border:0;border-radius:0;box-shadow:none;}}
/* An authored logo field takes priority over the recovered CSS background. */
.allianz-legacy .navbar>.container-fluid .navbar-brand:has(img){background:none;text-indent:0;padding:0;}
.allianz-legacy .navbar>.container-fluid .navbar-brand img{display:block;width:100%;height:100%;object-fit:contain;object-position:left center;}
/* Local public search and form states; no production widget code or form action. */
.allianz-local-search{padding:20px 0;}
.allianz-local-search .input-group{width:100%;max-width:600px;}
.allianz-local-search-results{margin-top:24px;}
.allianz-local-search-results ol{padding-left:24px;}
.allianz-local-search-results li{margin-bottom:24px;}
.allianz-local-search-results h3{margin:0 0 8px;}
.allianz-local-form .allianz-local-privacy{font-size:14px;color:#5b5b5b;margin-bottom:24px;}
.allianz-local-form .allianz-local-secondary{clear:both;padding-top:10px;}
.allianz-local-form .field-validation-error{display:block;color:#b30020;margin-top:4px;}
.allianz-local-form .validation-summary-errors{padding:12px;border-left:3px solid #b30020;margin-bottom:20px;}
/* The source clearfix only covers .form-horizontal. The native form uses
 * .cui-portletform, so every floated row needs its own formatting context. */
.allianz-legacy .allianz-local-form .form-group{display:flow-root;clear:both;}
.allianz-legacy .allianz-local-form fieldset.form-group{border:0;padding:0;margin-left:0;margin-right:0;min-width:0;width:100%;}
.allianz-legacy .allianz-local-form fieldset.form-group legend{font:inherit;border:0;margin-bottom:0;}
.allianz-local-form .allianz-local-date .row{margin-left:-5px;margin-right:-5px;}
.allianz-local-form .allianz-local-date .row>div{padding-left:5px;padding-right:5px;}
.allianz-local-form .allianz-local-review dl>div{display:grid;grid-template-columns:minmax(120px,1fr) 2fr;gap:16px;padding:10px 0;border-bottom:1px solid #e5e5e5;}
.allianz-local-form .allianz-local-review dt{font-weight:700;}
.allianz-local-form .allianz-local-review dd{margin:0;overflow-wrap:anywhere;}
.allianz-local-form .allianz-local-actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-top:24px;}
.allianz-local-form .allianz-local-account-overlay{position:fixed;inset:0;background:#0006;z-index:1100;display:grid;place-items:center;padding:20px;}
.allianz-local-form .allianz-local-account-overlay>.modal-content{width:min(100%,520px);padding:24px;background:#fff;}
@media(min-width:768px){.allianz-legacy .allianz-local-form fieldset.form-group legend{width:25%;}.allianz-legacy .allianz-local-form .form-group>.col-sm-9{width:75%;}}
@media(max-width:767px){.allianz-local-form .allianz-local-review dl>div{display:block;}.allianz-local-form .allianz-local-review dd{margin-top:4px;}}
